maria: updated the draft with a small table and an example. added this JS snippet and a Python sample for Retry-After parsing:
```js
// simplistic Retry-After handling
const wait = ms => new Promise(r => setTimeout(r, ms));
async function callWithRetry(api, opts) {
  for (let i = 0; i < 3; i++) {
    const res = await api.request(opts);
    if (res.status !== 429) return res;
    const ra = parseInt(res.headers['retry-after'] || '1', 10) * 1000;
    await wait(ra + 200); // jitter
  }
  throw new Error('rate-limited');
}
```
```py
# python Retry-After naive example
import time
import requests

def call_with_retry(url, max_retries=3):
    for i in range(max_retries):
        r = requests.post(url, json={})
        if r.status_code != 429:
            return r
        ra = int(r.headers.get('Retry-After', '1'))
        time.sleep(ra + 0.2)
    raise RuntimeError('rate-limited')
```
